import{_ as d,C as r,o as s,c as i,j as t,a as o,E as n,a3 as u}from"./chunks/framework.D6kVjW99.js";const V=JSON.parse('{"title":"رسائل خطأ لوحة الإدارة (فهرس)","description":"فهرس رسائل خطأ لوحة الإدارة: ماذا تقول الرسالة، ولماذا تظهر، والدرس الذي يقدّم الحل.","frontmatter":{"title":"رسائل خطأ لوحة الإدارة (فهرس)","description":"فهرس رسائل خطأ لوحة الإدارة: ماذا تقول الرسالة، ولماذا تظهر، والدرس الذي يقدّم الحل.","order":90,"role":["TOUS"],"appareil":"WEB","duree":"دقيقتان","objectif":"العثور في ثوانٍ على سبب رسالة الخطأ وعلى الصفحة التي تشرح ما يجب فعله.","prerequis":["أن تكون قد دوّنت الرسالة كما تظهر على الشاشة بالضبط (أو التقطت لها صورة شاشة)."],"parcours":["H9-09"],"capturesLangue":{},"capturesCouvertes":true},"headers":[],"relativePath":"ar/guide/depannage/messages-d-erreur.md","filePath":"ar/guide/depannage/messages-d-erreur.md","lastUpdated":1794455775000}'),l={name:"ar/guide/depannage/messages-d-erreur.md"};function c(g,e,h,m,p,f){const a=r("FicheTuto");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"رسائل-خطأ-لوحة-الإدارة-فهرس",tabindex:"-1"},[o("رسائل خطأ لوحة الإدارة (فهرس) "),t("a",{class:"header-anchor",href:"#رسائل-خطأ-لوحة-الإدارة-فهرس","aria-label":'Permalink to "رسائل خطأ لوحة الإدارة (فهرس)"'},"​")],-1)),n(a),e[1]||(e[1]=u('<p>ظهرت رسالة باللون الأحمر تحت نموذج، أو في شريط، أو في نافذة؟ ابحث عنها أدناه (أو اكتب بضع كلمات من الرسالة في <strong>البحث</strong> بمركز المساعدة، أعلى الصفحة). يذكر كل سطر السبب المحتمل والدرس الذي يشرح الحل خطوة بخطوة.</p><p><strong>ترتيب الفهرس:</strong> يتبع هذا الفهرس الترتيب الأبجدي للرسالة الفرنسية الأصلية (حسب أول كلمة فيها، دون اعتبار علامات التنصيص « » ولا الحركات)، لأن الترتيب الأبجدي اللاتيني لا ينطبق على العربية. لذلك تحمل الأقسام حروفًا لاتينية (A، C، D…). لكل رسالة نعرض نصها كما يظهر على الشاشة بالعربية، ثم بين قوسين النص الفرنسي الأصلي لتسهيل البحث. الرسائل التي تتلقاها البرامج الخارجية عبر الواجهة البرمجية العامة تبقى بالفرنسية، فنعرض النص الفرنسي كما هو مع معناه بالعربية.</p><p>الأجزاء التي تتغيّر من حالة إلى أخرى (اسم منتج، عدد، اسم باقتك) مستبدلة بـ <strong>…</strong> أو معروضة بمثال من المتجر التجريبي.</p><h2 id="عائلات-الرسائل" tabindex="-1">عائلات الرسائل <a class="header-anchor" href="#عائلات-الرسائل" aria-label="Permalink to &quot;عائلات الرسائل&quot;">​</a></h2><p>قبل البحث عن رسالة بعينها، تعرّف على عائلتها: غالبًا ما يكون التصرّف المطلوب هو نفسه.</p><table tabindex="0"><thead><tr><th>تحتوي الرسالة على…</th><th>ماذا تعني</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td><strong>في مكان آخر</strong> (modifié(s) ailleurs)، <strong>في الأثناء</strong> (entre-temps، concurremment)، <strong>نسخة قديمة</strong> (Version périmée)</td><td>شخص آخر (أو أنت، في علامة تبويب أخرى) حفظ الصفحة نفسها بينما كنت تعدّلها. يرفض Vendora الكتابة فوق عمله.</td><td>تُعاد عادةً أحدث نسخة تلقائيًا: أعد تغييراتك ثم احفظ. وإلا، أعد تحميل الصفحة.</td></tr><tr><td><strong>دور المدير مطلوب</strong> (Rôle Manager requis)، <strong>دور المالك أو المسؤول مطلوب</strong> (Rôle Propriétaire ou Administrateur requis)، <strong>مخصّص لـ…</strong> (Réservé au…)، <strong>المالك وحده…</strong> (Seul le propriétaire…)، <strong>للقراءة فقط: …</strong> (Lecture seule : …)</td><td>دورك في المتجر المعروض لا يسمح بهذا الإجراء.</td><td>تحقّق من المتجر المختار أعلى الصفحة، ثم اطلب من المالك تغيير دورك (<a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق</a>).</td></tr><tr><td><strong>غير مشمول في باقة…</strong> (n&#39;est pas inclus dans la formule)، <strong>تم بلوغ حدّ باقة…</strong> (Limite de la formule … atteinte)</td><td>اشتراكك في Vendora لا يتضمّن هذه الوحدة، أو بلغت العدد الأقصى من المتاجر أو الأجهزة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/abonnement">إدارة الاشتراك</a>، أو اتصل بـ Vendora.</td></tr><tr><td><strong>حساب للقراءة فقط</strong> (Compte en lecture seule)، <strong>الحساب معلّق</strong> (Compte suspendu)</td><td>الاشتراك معلّق أو ملغى: يمكن الاطلاع على لوحة الإدارة لكن لا يمكن تعديلها. تواصل نقاط البيع البيع.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/depannage/compte-suspendu">حساب معلّق، نهاية الفترة التجريبية</a>.</td></tr><tr><td><strong>تعذّر تحميل…</strong> (Impossible de charger…)، <strong>… غير متاح(ة).</strong> (… indisponible(s).)، <strong>تعذّر التحميل</strong> (Chargement impossible)، <strong>الخادم لا يستجيب</strong> (le serveur ne répond pas)، <strong>تحقّق من اتصالك</strong> (vérifiez votre connexion)</td><td>لم تحصل لوحة الإدارة على ردّ من الخادم: انقطاع الإنترنت، أو خدمة غير متاحة مؤقتًا.</td><td>تحقّق من اتصالك، انتظر قليلًا ثم أعد تحميل الصفحة (مفتاح F5).</td></tr><tr><td><strong>تم رفض…</strong> (… refusé(e).) متبوعة بشرح (مثل <strong>تم رفض الحفظ.</strong> (Enregistrement refusé.)، <strong>تم رفض النشر.</strong> (Publication refusée.))</td><td>رفض الخادم العملية؛ والجملة الثانية تقول لماذا.</td><td>ابحث عن الجملة الثانية في الفهرس أدناه.</td></tr><tr><td><strong>تعذّر…</strong> (… impossible.) وحدها (مثل <strong>تعذر التعطيل.</strong> (Désactivation impossible.)، <strong>تعذّر التصدير.</strong> (Export impossible.))</td><td>لم تكتمل العملية، دون تفاصيل إضافية (غالبًا بسبب انقطاع الشبكة).</td><td>أعد تحميل الصفحة وأعد المحاولة؛ إذا تكرّر الأمر، دوّن الوقت واتصل بالدعم.</td></tr></tbody></table><h2 id="الفهرس-حسب-الرسالة-الفرنسية" tabindex="-1">الفهرس حسب الرسالة الفرنسية <a class="header-anchor" href="#الفهرس-حسب-الرسالة-الفرنسية" aria-label="Permalink to &quot;الفهرس حسب الرسالة الفرنسية&quot;">​</a></h2><p><strong>الانتقال إلى الحرف:</strong> <a href="#lettre-0-9">0–9</a> · <a href="#lettre-a">A</a> · <a href="#lettre-c">C</a> · <a href="#lettre-d">D</a> · <a href="#lettre-e">E</a> · <a href="#lettre-f">F</a> · <a href="#lettre-i">I</a> · <a href="#lettre-l">L</a> · <a href="#lettre-m">M</a> · <a href="#lettre-n">N</a> · <a href="#lettre-p">P</a> · <a href="#lettre-r">R</a> · <a href="#lettre-s">S</a> · <a href="#lettre-t">T</a> · <a href="#lettre-u">U</a> · <a href="#lettre-v">V</a></p><h2 id="lettre-0-9" tabindex="-1">0–9 <a class="header-anchor" href="#lettre-0-9" aria-label="Permalink to &quot;0–9 {#lettre-0-9}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>5 منتج يستخدم هذه النسبة: انقلها أولًا إلى نسبة أخرى (5 produit(s) utilisent ce taux : basculez-les d&#39;abord vers un autre taux)</td><td>تعطّل أو تحذف نسبة أداء على القيمة المضافة لا تزال منتجات تحملها.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/taux-de-tva">إدارة نسب الأداء على القيمة المضافة (الافتراضية، إعادة التعيين)</a></td></tr><tr><td>8 أحرف على الأقل. (8 caractères au moins.)</td><td>كلمة المرور المختارة عند التسجيل قصيرة جدًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/creer-son-espace">إنشاء فضاء Vendora الخاص بك</a></td></tr></tbody></table><h2 id="lettre-a" tabindex="-1">A <a class="header-anchor" href="#lettre-a" aria-label="Permalink to &quot;A {#lettre-a}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>التنبيهات غير متاحة (يلزم دور المدير في هذا المتجر). (Alertes indisponibles (rôle Manager requis sur ce magasin).)</td><td>دورك في المتجر المعروض لا يمنحك الوصول إلى تنبيهات لوحة القيادة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/tableau-de-bord">التعرّف على لوحة القيادة وقائمة « بداية جيدة »</a></td></tr><tr><td>«مكافحة الاحتيال» غير مشمول في باقة Restaurant. اتصل بـ Vendora لإضافته. (« Anti-fraude » n&#39;est pas inclus dans la formule Restaurant. Contactez Vendora pour l&#39;ajouter.)</td><td>الوحدة المطلوبة ليست جزءًا من باقتك (يتغيّر اسم الوحدة واسم الباقة).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/anti-fraude">مراقبة مكافحة الاحتيال</a></td></tr><tr><td>الكريدي غير مسدّد (…): حصّل الدفع أو سجّله كخسارة أولًا (Ardoise non soldée (…) : encaissez le règlement ou passez-la en perte d&#39;abord)</td><td>تريد إخفاء هوية حريف أو تعطيله وهو لا يزال مدينًا بمال.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/clients/fiches-clients">إنشاء الحرفاء والعثور عليهم</a></td></tr><tr><td>الشهادة مخصّصة للمتاجر الخاضعة للوحدة الجبائية الفرنسية (Attestation réservée aux magasins soumis au module fiscal France)</td><td>الشهادة الجبائية لا تخصّ إلا المتاجر الموجودة في فرنسا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/conformite-fiscale">المطابقة الجبائية: السلامة، الإقفالات، الأرشيف</a></td></tr><tr><td>يلزم مستلم واحد على الأقل لتفعيل الملخّص (Au moins un destinataire pour activer le récapitulatif)</td><td>تم تفعيل الملخص اليومي دون أي عنوان بريد إلكتروني.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/recapitulatif-quotidien">تلقّي الملخص اليومي</a></td></tr><tr><td>مستوى واحد على الأقل لتفعيل الولاء (Au moins un palier pour activer la fidélité)</td><td>تم تفعيل برنامج الولاء دون أي مستوى مكافأة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/clients/fidelite">إعداد برنامج ولاء</a></td></tr><tr><td>يجب أن تكون خطوة واحدة على الأقل إلزامية (الحد الأدنى ≥ 1). (Au moins une étape doit être obligatoire (minimum ≥ 1).)</td><td>كل خطوات الوجبة المركبة اختيارية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/formules">إنشاء وجبة مركبة (قائمة) بخطوات</a></td></tr><tr><td>المحور «Parfum»: قيمة واحدة على الأقل (Axe « Parfum » : au moins une valeur)</td><td>محور متغيّرات بلا أي قيمة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/variantes">منتجات بمتغيّرات (المقاس، اللون، النكهة)</a></td></tr></tbody></table><h2 id="lettre-c" tabindex="-1">C <a class="header-anchor" href="#lettre-c" aria-label="Permalink to &quot;C {#lettre-c}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>الصنف مستخدم من قبل …: أزله أولًا (Catégorie utilisée par … : retirez-la d&#39;abord)</td><td>الفئة المراد حذفها لا تزال تحتوي على منتجات.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/categories">تنظيم الأصناف</a></td></tr><tr><td>تم استلام هذا الأمر بالفعل: أغلق الباقي بدلاً من إلغائه. (Ce bon a déjà été réceptionné : clôturez le reliquat au lieu de l&#39;annuler.)</td><td>أمر شراء تم استلامه (ولو جزئيًا) لا يمكن إلغاؤه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr><tr><td>لم يعد أمر الشراء هذا (…) قابلاً للتعديل: لا يُعدَّل إلا المسودّة. (Ce bon de commande (…) n&#39;est plus modifiable : seul un brouillon se modifie.)</td><td>أُرسل الأمر إلى المزوّد: لم يعد قابلًا للتعديل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr><tr><td>هذا الزر يتجاوز الشبكة أو يتداخل مع زر آخر. (Ce bouton déborde de la grille ou chevauche un autre bouton.)</td><td>زر شاشة البيع يخرج من الشبكة أو يتراكب مع زر آخر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/ecran-de-vente">تصميم شاشة البيع (المربعات، الأزرار السريعة)</a></td></tr><tr><td>انتهت صلاحية هذا الرابط (72 ساعة). اطلب من مديرك إعادة إرسال الدعوة. (Ce lien a expiré (72 h). Demandez à votre manager de renvoyer l&#39;invitation.)</td><td>مضى على رابط الدعوة أكثر من ثلاثة أيام.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/accepter-une-invitation">قبول دعوة</a></td></tr><tr><td>هذا المتجر مؤرشف: أعِد تشغيله (صفحة المتاجر) قبل أن تقرن به جهازًا. (Ce magasin est archivé : remettez-le en service (page Magasins) avant d&#39;y appairer un appareil.)</td><td>رمز الاقتران يستهدف متجرًا مؤرشفًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/appairer-un-appareil">إقران نقطة بيع أو هاتف (رمز، QR)</a></td></tr><tr><td>تم اعتماد هذا الجرد بالفعل: أعد تحميل الصفحة. (Cet inventaire est déjà validé : rechargez la page.)</td><td>تم اعتماد الجرد في الأثناء (من قِبلك في علامة تبويب أخرى، أو من قِبل زميل).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/inventaire">إطلاق جرد واعتماده</a></td></tr><tr><td>لهذا البريد الإلكتروني حساب مسبقًا. سجّل الدخول أو استخدم « نسيت كلمة المرور ». (Cette adresse e-mail a déjà un compte. Connectez-vous ou utilisez « Mot de passe oublié ».)</td><td>البريد الإلكتروني المُدخل عند التسجيل يطابق حسابًا موجودًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/creer-son-espace">إنشاء فضاء Vendora الخاص بك</a></td></tr><tr><td>تم رفض تغيير الدور. لا يمكنك تغيير دورك بنفسك (Changement de rôle refusé. Impossible de changer votre propre rôle)</td><td>لا يمكن لأحد تعديل دوره بنفسه، ولا حتى المالك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>تعذّر التحميل (Chargement impossible)</td><td>لم تحصل الصفحة على ردّ من الخادم: أعد تحميلها.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/liste-des-produits">البحث عن المنتجات وتصفيتها وتفعيلها / تعطيلها</a></td></tr><tr><td>اختر نسبة الأداء على القيمة المضافة. (Choisissez un taux de TVA.)</td><td>المنتج ليست له نسبة أداء على القيمة المضافة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>اختاروا منصة معتمدة قبل تفعيل الإرسال (Choisissez une plateforme agréée avant d&#39;activer la transmission)</td><td>تم تفعيل الإبلاغ الإلكتروني دون اختيار منصة رقمنة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/e-reporting">الإبلاغ الإلكتروني عن الأداء على القيمة المضافة للمبيعات للأفراد (فرنسا)</a></td></tr><tr><td>رقم التحقق غير صحيح: يجب أن يكون الرقم الأخير … (Clé de contrôle invalide : le dernier chiffre devrait être …)</td><td>في الرمز الشريطي EAN المُدخل أو المستورد خطأ في الكتابة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/codes-barres">الرموز الشريطية: الإدخال، المسح، توليد رموز داخلية</a></td></tr><tr><td>تمّ إخفاء هوية العميل: لم يعد بالإمكان تعديل البطاقة (Client anonymisé : la fiche n&#39;est plus modifiable)</td><td>تم إخفاء هوية البطاقة (الحق في المحو): هذا نهائي.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/clients/fiches-clients">إنشاء الحرفاء والعثور عليهم</a></td></tr><tr><td>إغلاقات يومية ناقصة (7/37): أنشئ الإغلاقات المستحقة قبل الأرشفة (Clôtures journalières manquantes (7/37) : générez les clôtures dues avant d&#39;archiver)</td><td>بعض الأيام بلا إقفال: لا يمكن إنتاج الأرشيف الجبائي.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/conformite-fiscale">المطابقة الجبائية: السلامة، الإقفالات، الأرشيف</a></td></tr><tr><td>رمز اقتران غير صالح — تحقّق من الإدخال. (Code d&#39;appairage invalide — vérifiez la saisie.)</td><td>على الجهاز: الرمز المكتوب لا يطابق أي رمز مولَّد.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/appairer-un-appareil">إقران نقطة بيع أو هاتف (رمز، QR)</a></td></tr><tr><td>رمز منتهي الصلاحية أو مستعمل — أنشئ رمزاً جديداً في لوحة الإدارة. (Code expiré ou déjà utilisé — générez-en un nouveau au back-office.)</td><td>انتهت صلاحية رمز الاقتران (15 دقيقة) أو سبق استعماله (النص نفسه على الجهاز وفي ردود الخادم).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/appairer-un-appareil">إقران نقطة بيع أو هاتف (رمز، QR)</a></td></tr><tr><td>عمود (أعمدة) غير معروف: … (Colonne(s) inconnue(s) : …)</td><td>يحتوي ملف CSV على عناوين لا يتعرّف عليها الاستيراد.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>حساب للقراءة فقط (الاشتراك معلّق أو ملغى): يستمر البيع على نقاط البيع الخاصة بك. اتصل بـ Vendora من صفحة الاشتراك. (Compte en lecture seule (abonnement suspendu ou résilié) : la vente continue sur vos caisses. Contactez Vendora depuis la page Abonnement.)</td><td>الاشتراك معلّق أو ملغى: ترفض لوحة الإدارة أي تعديل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/depannage/compte-suspendu">حساب معلّق، نهاية الفترة التجريبية</a></td></tr><tr><td>حساب للقراءة فقط: تم رفض التعديل. (Compte en lecture seule : modification refusée.)</td><td>السبب نفسه، رسالة قصيرة تظهر في شريط.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/depannage/compte-suspendu">حساب معلّق، نهاية الفترة التجريبية</a></td></tr><tr><td>الحساب معلّق: لوحة الإدارة للقراءة فقط. يستمر البيع. اتصل بـ Vendora. (Compte suspendu : back-office en lecture seule. La vente continue. Contactez Vendora.)</td><td>شريط يظهر أعلى كل الصفحات خلال فترة التعليق.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/depannage/compte-suspendu">حساب معلّق، نهاية الفترة التجريبية</a></td></tr><tr><td>الحساب معلّق أو ملغى: لا يمكن إقران أي جهاز جديد. اتصل بـ Vendora. (Compte suspendu ou résilié : aucun nouvel appareil ne peut être appairé. Contactez Vendora.)</td><td>الاقتران محظور ما دام الحساب معلّقًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/depannage/compte-suspendu">حساب معلّق، نهاية الفترة التجريبية</a></td></tr><tr><td>تم تعديل الإعدادات في الأثناء (Configuration modifiée concurremment)</td><td>عدّل شخص آخر الكشك في الوقت نفسه معك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/bornes">الإشراف على الأكشاك</a></td></tr><tr><td>تعذّر تسجيل الدخول: الخادم لا يستجيب. تحقّق من اتصالك بالإنترنت ثم أعد المحاولة. (Connexion impossible : le serveur ne répond pas. Vérifiez votre connexion Internet, puis réessayez.)</td><td>لا تصل لوحة الإدارة إلى الخادم (انقطاع الشبكة، خدمة غير متاحة).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-connecter">تسجيل الدخول إلى لوحة الإدارة، نسيت كلمة المرور</a></td></tr><tr><td>تم رفض التصحيح. السبب إلزامي (Correction refusée. Motif obligatoire)</td><td>يجب تبرير تصحيح حركة مخزون.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/journal-du-stock">فهم سجل المخزون</a></td></tr><tr><td>تم رفض التصحيح. رمز PIN غير صالح (Correction refusée. PIN invalide)</td><td>رمز PIN الذي أُدخل بصفته رمز مدير لتصحيح الحركة خاطئ.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/journal-du-stock">فهم سجل المخزون</a></td></tr><tr><td>اللون الأساسي بصيغة #RRGGBB. (Couleur primaire au format #RRGGBB.)</td><td>اللون المُدخل ليس رمزًا سداسيًا عشريًا من ستة خانات.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/apparence">تخصيص المظهر (الشعار، الألوان، الكشك)</a></td></tr><tr><td>تم رفض الإنشاء. البريد الإلكتروني مستخدم بالفعل (Création refusée. E-mail déjà utilisé)</td><td>أحد أعضاء الفريق لديه هذا البريد الإلكتروني بالفعل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>تم رفض الإنشاء. رمز PIN مستخدم بالفعل في هذا المتجر، اختر رمزًا آخر (Création refusée. PIN déjà utilisé dans ce magasin, choisissez-en un autre)</td><td>لا يمكن لعضوين في المتجر نفسه أن يكون لهما رمز PIN نفسه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr></tbody></table><h2 id="lettre-d" tabindex="-1">D <a class="header-anchor" href="#lettre-d" aria-label="Permalink to &quot;D {#lettre-d}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>تمت معالجته في مكان آخر — أُعيد تحميل القائمة. (Déjà traité ailleurs — liste rechargée.)</td><td>عالج مسؤول آخر هذا التكرار في الحرفاء قبلك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/clients/doublons-clients">دمج الحرفاء المكرّرين</a></td></tr><tr><td>تعذر التعطيل. (Désactivation impossible.)</td><td>لم يستجب الخادم لتعطيل الكشك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/bornes">الإشراف على الأكشاك</a></td></tr><tr><td>عملة المزوّد (…) تختلف عن عملة المتجر (…): تعدّد العملات غير مدعوم (Devise du fournisseur (…) différente de celle du magasin (…) : multi-devises hors périmètre)</td><td>يفوتر المورّد بعملة غير عملة المتجر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr></tbody></table><h2 id="lettre-e" tabindex="-1">E <a class="header-anchor" href="#lettre-e" aria-label="Permalink to &quot;E {#lettre-e}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>البريد الإلكتروني أو كلمة المرور غير صحيحة. (E-mail ou mot de passe incorrect.)</td><td>بيانات دخول خاطئة، أو الوصول إلى لوحة الإدارة غير مفعّل لهذا الحساب.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-connecter">تسجيل الدخول إلى لوحة الإدارة، نسيت كلمة المرور</a></td></tr><tr><td>الإبلاغ الإلكتروني مخصص للمتاجر على الوحدة الضريبية FR (فرنسا) (E-reporting réservé aux magasins du module fiscal FR (pays France))</td><td>إرسال الإبلاغ الإلكتروني لا يخصّ إلا المتاجر الفرنسية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/e-reporting">الإبلاغ الإلكتروني عن الأداء على القيمة المضافة للمبيعات للأفراد (فرنسا)</a></td></tr><tr><td>تم رفض الحفظ. رمز الميزان مستعمل من قبل منتج آخر (Enregistrement refusé. Code balance déjà utilisé par un autre produit)</td><td>رمز الميزان (PLU) المُدخل يخصّ منتجًا آخر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/vente-au-poids">البيع بالوزن ورموز الميزان</a></td></tr><tr><td>تم رفض الحفظ. الرمز الشريطي مستخدم بالفعل لمنتج آخر (Enregistrement refusé. Code-barres déjà utilisé par un autre produit)</td><td>الرمز الشريطي المُدخل يخصّ منتجًا آخر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/codes-barres">الرموز الشريطية: الإدخال، المسح، توليد رموز داخلية</a></td></tr><tr><td>تم رفض الحفظ. الرموز التي تبدأ بـ 20 محجوزة للرموز الداخلية المُولَّدة (تم رفض الحفظ. Les codes commençant par 20 sont réservés aux codes internes générés)</td><td>الرموز الشريطية التي تبدأ بـ 20 مخصّصة للرموز التي يولّدها Vendora.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/codes-barres">الرموز الشريطية: الإدخال، المسح، توليد رموز داخلية</a></td></tr><tr><td>تم رفض الحفظ. يتطلب دور المدير في هذا المتجر (Enregistrement refusé. Rôle Manager requis sur ce magasin)</td><td>دورك لا يسمح بتعديل كتالوج هذا المتجر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>تم رفض الحفظ. المنتج ذو المتغيّرات ليس له رمز شريطي ولا رمز ميزان ولا بيع بالوزن: تُضبط على كل متغيّر (تم رفض الحفظ. Un produit à variantes n&#39;a ni code-barres, ni code balance, ni vente au poids : ils se règlent sur chaque variante)</td><td>تُدخل الرموز على كل متغيّر، وليس على المنتج الأم.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/vente-au-poids">البيع بالوزن ورموز الميزان</a></td></tr><tr><td>التصديرات المحاسبية: يتطلب دور المالك أو المسؤول (Exports comptables : rôle Propriétaire ou Administrateur requis)</td><td>المالك والمسؤولون وحدهم ينزّلون التصديرات المحاسبية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/exports-comptables">التصدير للمحاسب (اليوميات وملف FEC)</a></td></tr></tbody></table><h2 id="lettre-f" tabindex="-1">F <a class="header-anchor" href="#lettre-f" aria-label="Permalink to &quot;F {#lettre-f}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>الفاتورة … مسجّلة مسبقًا لهذا المورّد (Facture … déjà enregistrée pour ce fournisseur)</td><td>رقم فاتورة المزوّد هذا مسجّل بالفعل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/dettes-fournisseurs">متابعة فواتير المزوّدين وديونهم</a></td></tr><tr><td>الملف كبير جدًا (5 ميغابايت كحد أقصى) (Fichier trop lourd (5 Mo au plus))</td><td>الملف المُرسل (صورة منتج) يتجاوز 5 ميغابايت.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/photos-produit">إضافة صور إلى منتج</a></td></tr><tr><td>الملف طويل جدًا: 10 000 سطر كحد أقصى (Fichier trop long : 10 000 lignes au plus)</td><td>ملف استيراد الكتالوج يتجاوز 10 000 سطر: قسّمه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>ملف فارغ: يجب أن يحتوي السطر الأول على العناوين (Fichier vide : la première ligne doit porter les en-têtes)</td><td>ملف CSV فارغ أو بلا سطر عناوين.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>الصيغ المقبولة: PNG أو JPEG أو WebP. (Format accepté : PNG, JPEG ou WebP.)</td><td>الشعار (أو صورة الكشك) ليس بصيغة PNG ولا JPEG ولا WebP.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/apparence">تخصيص المظهر (الشعار، الألوان، الكشك)</a></td></tr><tr><td>صيغة مرفوضة (…): تُقبل PNG أو JPEG أو WebP (Format refusé (…) : PNG, JPEG ou WebP acceptés)</td><td>الملف المُرسل (صورة، شعار) بصيغة أخرى مذكورة بين قوسين (HEIC، GIF، SVG+XML…).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/photos-produit">إضافة صور إلى منتج</a></td></tr><tr><td>عُدّلت الوجبة المركبة في مكان آخر في الأثناء: أعد التحميل للانطلاق من آخر نسخة (ستُفقد تغييراتك غير المنشورة). (Formule modifiée ailleurs entre-temps : rechargez pour repartir de la dernière version (vos changements non publiés seront perdus).)</td><td>نشر شخص آخر الوجبة المركبة أثناء تعديلك لها.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/formules">إنشاء وجبة مركبة (قائمة) بخطوات</a></td></tr><tr><td>مورّد معطّل: لم يعد متاحًا في طلبية جديدة (Fournisseur désactivé : plus proposable sur un nouveau bon)</td><td>تم تعطيل المزوّد المختار.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/fournisseurs">إدارة المزوّدين وأسعارهم</a></td></tr></tbody></table><h2 id="lettre-i" tabindex="-1">I <a class="header-anchor" href="#lettre-i" aria-label="Permalink to &quot;I {#lettre-i}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>معرّف القارئ إلزامي خارج المحاكاة (Identifiant du lecteur obligatoire hors simulation)</td><td>جهاز الدفع في الكشك في وضع البيئة التجريبية أو الإنتاج دون معرّف قارئ.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/bornes">الإشراف على الأكشاك</a></td></tr><tr><td>يلزم عمود واحد على الأقل: name (الاسم) أو id أو barcode (الرمز الشريطي) (Il faut au moins une colonne name (nom), id ou barcode (code-barres))</td><td>الملف لا يسمح بالتعرّف على المنتجات.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>تم تطبيق الاستيراد بالفعل (Import déjà appliqué)</td><td>تم تطبيق معاينة هذا الاستيراد بالفعل: أعد التحليل لاستيراد جديد.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>تعذّر تحميل الفريق. (Impossible de charger l&#39;équipe.)</td><td>تعذّرت قراءة قائمة الفريق (الشبكة، الصلاحيات).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>تعذّر تحميل المخزون: تحقّق من اتصالك ثم أعد تحميل الصفحة. (Impossible de charger le stock : vérifiez votre connexion, puis rechargez la page.)</td><td>الخادم لا يستجيب: تحقّق من الاتصال ثم أعد التحميل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/suivre-son-stock">متابعة المخزون والنفاد</a></td></tr><tr><td>التسجيل مغلق: اتصل بـ Vendora لفتح حسابك (Inscription fermée : contactez Vendora pour ouvrir votre espace)</td><td>التسجيل الحر معطّل: يُنشئ فريق Vendora الفضاء.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/creer-son-espace">إنشاء فضاء Vendora الخاص بك</a></td></tr><tr><td>تم إنشاء الدعوة لـ …، لكن البريد لم يُرسل (المزوّد غير مهيأ): استخدم « إعادة الإرسال » لاحقًا. (Invitation créée pour …, mais l&#39;e-mail n&#39;est pas parti (fournisseur non configuré) : utilisez « Renvoyer » plus tard.)</td><td>الدعوة موجودة لكن تعذّر إرسال البريد الإلكتروني.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>تم قبول الدعوة بالفعل (Invitation déjà acceptée)</td><td>سبق استعمال رابط الدعوة: سجّل الدخول كالمعتاد.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/accepter-une-invitation">قبول دعوة</a></td></tr><tr><td>تم رفض الدعوة. لا يمكنك دعوة مسؤول (دور أعلى من دورك) إلى هذا المتجر (Invitation refusée. Vous ne pouvez pas inviter un Administrateur (rôle supérieur au vôtre) dans ce magasin)</td><td>لا يمكنك دعوة إلا أدوار أدنى من دورك أو مساوية له.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr></tbody></table><h2 id="lettre-l" tabindex="-1">L <a class="header-anchor" href="#lettre-l" aria-label="Permalink to &quot;L {#lettre-l}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>البريد الإلكتروني غير صالح. (L&#39;adresse e-mail est invalide.)</td><td>البريد الإلكتروني المُدخل ليس بصيغة صحيحة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/creer-son-espace">إنشاء فضاء Vendora الخاص بك</a></td></tr><tr><td>البصمة لا تطابق المحتوى: ربما تم تعديل تقرير Z (L&#39;empreinte ne correspond pas au contenu : rapport Z possiblement altéré)</td><td>أعاد المتصفح حساب بصمة تقرير Z ولم يجد البصمة نفسها.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/caisse-paiements/rapports-z">قراءة تقارير Z وتنزيلها</a></td></tr><tr><td>يحتوي الصنف على 2 صنف فرعي: انقلها أو احذفها أولًا (La catégorie contient 2 sous-catégorie(s) : déplacez-les ou supprimez-les d&#39;abord)</td><td>لا يمكن حذف صنف يحتوي على أصناف فرعية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/categories">تنظيم الأصناف</a></td></tr><tr><td>لا يمكن تغيير العملة بعد أول عملية بيع في المتجر (La devise ne change plus après la première vente du magasin)</td><td>تُثبَّت عملة المتجر منذ أول عملية بيع.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>تم تعديل السياسة في مكان آخر: أُعيد تحميل أحدث نسخة. (La politique a été modifiée ailleurs : la dernière version a été rechargée.)</td><td>نشر شخص آخر سياسة التحصيل عند الطاولة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/encaissement-a-la-table">اختيار طريقة التحصيل عند الطاولة</a></td></tr><tr><td>الطاولة «T3» موجودة بالفعل في المتجر. (La table « T3 » existe déjà dans le magasin.)</td><td>لا يمكن أن تحمل طاولتان في المتجر نفسه الاسم نفسه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/plan-de-salle">رسم مخطط القاعة (المناطق، الطاولات)</a></td></tr><tr><td>لا يمكن أرشفة آخر متجر نشط (Le dernier magasin actif ne peut pas être archivé)</td><td>يجب أن يبقى متجر واحد على الأقل في الخدمة دائمًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>تعذّر تحليل الملف. (Le fichier n&#39;a pas pu être analysé.)</td><td>الملف ليس CSV مقروءًا (الترميز، الفاصل، الصيغة).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>يجب أن يكون المتجر المصدر والمتجر الوجهة مختلفين (Le magasin source et le magasin destination doivent être différents)</td><td>يتم التحويل بين متجرين مختلفين.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/transferts">تحويل المخزون بين المتاجر</a></td></tr><tr><td>الحد الأدنى يتجاوز الحد الأقصى. (Le minimum dépasse le maximum.)</td><td>حدود خطوة في الوجبة المركبة معكوسة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/formules">إنشاء وجبة مركبة (قائمة) بخطوات</a></td></tr><tr><td>الاسم مطلوب. (Le nom est requis.)</td><td>المنتج بلا اسم.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>يجب أن يتكون رمز PIN من 4 إلى 6 أرقام. (Le PIN doit comporter 4 à 6 chiffres.)</td><td>رمز PIN المُدخل قصير جدًا أو طويل جدًا أو يحتوي على غير الأرقام.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>تم تعديل المخطط في مكان آخر: أُعيد تحميل أحدث نسخة، أعد تطبيق تغييراتك. (Le plan a été modifié ailleurs : la dernière version a été rechargée, réappliquez vos changements.)</td><td>نشر شخص آخر مخطط القاعة بينما كنت تعدّله.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/plan-de-salle">رسم مخطط القاعة (المناطق، الطاولات)</a></td></tr><tr><td>الدفعة تتجاوز الرصيد المتبقي للفاتورة (…). (Le règlement dépasse le solde restant de la facture (…).)</td><td>الدفعة المُدخلة تتجاوز المتبقي للدفع من فاتورة المورّد (المذكور بين قوسين).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/dettes-fournisseurs">متابعة فواتير المزوّدين وديونهم</a></td></tr><tr><td>يتكوّن رقم SIREN من 9 أرقام (Le SIREN compte 9 chiffres)</td><td>رقم SIREN المُدخل في الإعدادات المحاسبية غير صحيح الصيغة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/exports-comptables">التصدير للمحاسب (اليوميات وملف FEC)</a></td></tr><tr><td>لا يمكن تعطيل النسبة الافتراضية: اختر أولًا نسبة افتراضية أخرى (Le taux par défaut ne peut pas être désactivé : choisissez d&#39;abord un autre taux par défaut)</td><td>يجب أن تبقى نسبة الأداء على القيمة المضافة الافتراضية نشطة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/taux-de-tva">إدارة نسب الأداء على القيمة المضافة (الافتراضية، إعادة التعيين)</a></td></tr><tr><td>الجهاز المحاكى ممنوع في الإنتاج. (Le terminal simulé est interdit en production.)</td><td>جهاز الدفع المحاكى مخصّص للتجارب فقط.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/bornes">الإشراف على الأكشاك</a></td></tr><tr><td>للقراءة فقط: لا يعدّل هذه الإعدادات إلا المالك والمسؤولون. (Lecture seule : seuls le propriétaire et les administrateurs modifient ces réglages.)</td><td>دورك يسمح بالاطلاع على الصفحة دون تعديلها.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/recapitulatif-quotidien">تلقّي الملخص اليومي</a></td></tr><tr><td>تم تعديل محطات التحضير في مكان آخر: أُعيد تحميل أحدث نسخة. (Les postes ont été modifiés ailleurs : la dernière version a été rechargée.)</td><td>نشر شخص آخر محطات التحضير.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/postes-de-preparation">إنشاء محطات التحضير وتوجيه المنتجات (المطبخ، البار)</a></td></tr><tr><td>تتطلب التحويلات متجرين نشطين على الأقل. (Les transferts demandent au moins deux magasins actifs.)</td><td>مع متجر واحد، لا يوجد ما يُحوَّل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/transferts">تحويل المخزون بين المتاجر</a></td></tr><tr><td>الرابط مستخدم أو مستبدل — اطلب رابطًا جديدًا («نسيت كلمة المرور؟») (Lien déjà utilisé ou remplacé — demandez-en un nouveau (« Mot de passe oublié ? »))</td><td>سبق استعمال رابط إعادة التعيين أو أُرسل رابط أحدث.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-connecter">تسجيل الدخول إلى لوحة الإدارة، نسيت كلمة المرور</a></td></tr><tr><td>انتهت صلاحية الرابط — اطلب رابطًا جديدًا («نسيت كلمة المرور؟») (Lien expiré — demandez-en un nouveau (« Mot de passe oublié ? »))</td><td>انتهت صلاحية رابط إعادة تعيين كلمة المرور.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-connecter">تسجيل الدخول إلى لوحة الإدارة، نسيت كلمة المرور</a></td></tr><tr><td>… سطر به أخطاء (ربما تغيّر الكتالوج منذ التحليل): صحّح الملف وأعد تشغيل الاستيراد (… ligne(s) en erreur (le catalogue a peut-être changé depuis l&#39;analyse) : corrigez le fichier et relancez l&#39;import)</td><td>تغيّر الكتالوج بين المعاينة وتطبيق الاستيراد.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>Limite de 600 requêtes par minute atteinte (تظهر بالفرنسية؛ المعنى: «تم بلوغ حدّ 600 طلب في الدقيقة»)</td><td>تكامل يستدعي API بهذا المفتاح بشكل متكرر جدًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/cles-api">إنشاء مفاتيح API (التكاملات)</a></td></tr><tr><td>تم بلوغ حدّ باقة Restaurant: 1 متجر. اتصل بـ Vendora لإضافة المزيد. (Limite de la formule Restaurant atteinte : 1 magasin. Contactez Vendora pour en ajouter.)</td><td>باقتك لا تسمح بمتجر آخر (يتغيّر اسم الباقة والعدد).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>تم بلوغ حدّ باقة Restaurant: 6 جهاز بيع (دون الأكشاك). انتقل إلى باقة أعلى أو أضف جهازًا إضافيًا (صفحة الاشتراك). (Limite de la formule Restaurant atteinte : 6 appareils de vente (hors bornes). Passez à une formule supérieure ou ajoutez un appareil supplémentaire (page Abonnement).)</td><td>كل أجهزة البيع في الباقة مستعملة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/appairer-un-appareil">إقران نقطة بيع أو هاتف (رمز، QR)</a></td></tr><tr><td>الشعار كبير جدًا (2 ميغابايت كحد أقصى). (Logo trop lourd (2 Mo max).)</td><td>حجم الشعار يتجاوز 2 ميغابايت.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/apparence">تخصيص المظهر (الشعار، الألوان، الكشك)</a></td></tr></tbody></table><h2 id="lettre-m" tabindex="-1">M <a class="header-anchor" href="#lettre-m" aria-label="Permalink to &quot;M {#lettre-m}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>المتجر مؤرشف: لا تحويلات جديدة (Magasin archivé : aucun nouveau transfert)</td><td>المتجر المختار مؤرشف.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/transferts">تحويل المخزون بين المتاجر</a></td></tr><tr><td>رُفض التعديل — حساب للقراءة فقط (الاشتراك معلّق أو ملغى): يستمر البيع على نقاط البيع الخاصة بك. اتصل بـ Vendora من صفحة الاشتراك. (Modification refusée — Compte en lecture seule (abonnement suspendu ou résilié) : la vente continue sur vos caisses. Contactez Vendora depuis la page Abonnement.)</td><td>تمت محاولة تعديل أثناء تعليق الاشتراك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/abonnement">إدارة اشتراك Vendora وفواتيره</a></td></tr><tr><td>تم التعديل في مكان آخر — أعد التحميل. (Modifié ailleurs — rechargez.)</td><td>حفظ شخص آخر المنتج أثناء تعديلك له (أما الرمز الشريطي أو رمز الميزان المكرّر فيعرض سببه الخاص).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>كلمة المرور: 8 أحرف على الأقل (Mot de passe : 8 caractères minimum)</td><td>كلمة المرور الجديدة قصيرة جدًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-connecter">تسجيل الدخول إلى لوحة الإدارة، نسيت كلمة المرور</a></td></tr><tr><td>يجب ذكر سبب لرفض الحدث. (Motif obligatoire pour refuser un fait.)</td><td>رفض حدث مزامنة يتطلّب سببًا.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/synchronisation">معالجة أحداث المزامنة المرفوضة</a></td></tr><tr><td>السبب إلزامي لمعالجة تنبيه (Motif obligatoire pour traiter une alerte)</td><td>يُعالَج تنبيه مكافحة الاحتيال مع ذكر سبب.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/anti-fraude">مراقبة مكافحة الاحتيال</a></td></tr></tbody></table><h2 id="lettre-n" tabindex="-1">N <a class="header-anchor" href="#lettre-n" aria-label="Permalink to &quot;N {#lettre-n}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>اسم الجهاز إلزامي (Nom de l&#39;appareil obligatoire)</td><td>الجهاز المراد إقرانه بلا اسم.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/appareils">إدارة الأجهزة (إعادة التسمية، تغيير الدور، الاستبدال، الإلغاء)</a></td></tr><tr><td>اسم المتجر إلزامي (Nom du magasin obligatoire)</td><td>المتجر بلا اسم.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>رقم الدفعة وتاريخ الصلاحية إلزاميان لـ «…» (منتج متابَع الصلاحية). (Numéro de lot et DLC obligatoires pour « … » (produit suivi en péremption).)</td><td>عند الاستلام، سطر منتج متابَع الصلاحية بلا رقم دفعة أو تاريخ صلاحية (DLC).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr></tbody></table><h2 id="lettre-p" tabindex="-1">P <a class="header-anchor" href="#lettre-p" aria-label="Permalink to &quot;P {#lettre-p}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>صفحة مخصّصة للمالك والمسؤولين. (Page réservée au propriétaire et aux administrateurs.)</td><td>دورك لا يمنحك الوصول إلى الاشتراك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/abonnement">إدارة اشتراك Vendora وفواتيره</a></td></tr><tr><td>الفترة غير مغلقة: يجب أن تكون النهاية قبل اليوم (Période non close : la fin doit être antérieure à aujourd&#39;hui)</td><td>الأرشيف الجبائي يخصّ فترة منتهية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/conformite-fiscale">المطابقة الجبائية: السلامة، الإقفالات، الأرشيف</a></td></tr><tr><td>رمز PIN مستخدم بالفعل في هذا المتجر، اختر رمزًا آخر (PIN déjà utilisé dans ce magasin, choisissez-en un autre)</td><td>رمز PIN المختار عند تفعيل الدعوة مأخوذ بالفعل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/accepter-une-invitation">قبول دعوة</a></td></tr><tr><td>رمز PIN غير صالح (PIN invalide)</td><td>رمز PIN المدير المُدخل لاعتماد العملية خاطئ.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/suivre-son-stock">متابعة المخزون والنفاد</a></td></tr><tr><td>رمز PIN المدير مطلوب: أدخل رمز PIN لمدير المتجر للتأكيد. (PIN manager requis : saisissez le PIN d&#39;un manager du magasin pour valider.)</td><td>حقل رمز PIN كان فارغًا (أو لم تحدّد رمز PIN الخاص بك بعد).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/suivre-son-stock">متابعة المخزون والنفاد</a></td></tr><tr><td>«تعدد المتاجر» غير مشمول في باقتك: تبقى البيانات الحالية قابلة للاطلاع، أما الإنشاء والإعدادات فتتطلب باقة تشمله. (« Plusieurs magasins » n&#39;est pas inclus dans votre formule : l&#39;existant reste consultable, la création et les réglages demandent une formule qui l&#39;inclut.)</td><td>باقتك لا تتضمّن تعدّد المتاجر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/abonnement">إدارة اشتراك Vendora وفواتيره</a></td></tr><tr><td>تم رفض النشر. يجب أن تكون نقطة البيع الرئيسية نقطة بيع (REGISTER) نشطة في هذا المتجر (تم رفض النشر. La caisse principale doit être une caisse (REGISTER) active de ce magasin)</td><td>نقطة البيع الرئيسية المعيَّنة ملغاة، أو تابعة لمتجر آخر، أو ليست نقطة بيع.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/encaissement-a-la-table">اختيار طريقة الاستخلاص على الطاولة</a></td></tr><tr><td>تم رفض النشر. الطاولة «T9»: الموضع مشغول مسبقًا في «Salle» (تم رفض النشر. Table « T9 » : emplacement déjà occupé dans « Salle »)</td><td>طاولتان موضوعتان في المكان نفسه من المخطط.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/restaurant/plan-de-salle">رسم مخطط القاعة (المناطق، الطاولات)</a></td></tr></tbody></table><h2 id="lettre-r" tabindex="-1">R <a class="header-anchor" href="#lettre-r" aria-label="Permalink to &quot;R {#lettre-r}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>المرجع مستعمل من قبل منتج آخر (Référence déjà utilisée par un autre produit)</td><td>لا يمكن لمنتجين أن يحملا المرجع نفسه (لا فرق بين الأحرف الكبيرة والصغيرة).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>أدخل رقم SIREN للمؤسسة في إعدادات المحاسبة (Renseignez le SIREN de l&#39;entreprise dans les réglages comptables)</td><td>يتطلّب ملف FEC رقم SIREN للمؤسسة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/pilotage/exports-comptables">التصدير للمحاسب (اليوميات وملف FEC)</a></td></tr><tr><td>مخصّص للمالك والمسؤولين (Réservé au propriétaire et aux administrateurs.)</td><td>إجراء مقتصر على دوري المالك والمسؤول.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/cles-api">إنشاء مفاتيح API (التكاملات)</a></td></tr><tr><td>مخصّص لمديري المتجر. (Réservé aux gérants du magasin.)</td><td>صفحة مقتصرة على المديرين والمسؤولين والمالك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/bornes">الإشراف على الأكشاك</a></td></tr><tr><td>ألغِ أولًا الأجهزة النشطة في هذا المتجر: … (Révoquez d&#39;abord les appareils actifs de ce magasin : …)</td><td>لا يمكن أرشفة متجر ما دامت أجهزة مقترنة به.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>يتطلب دور المدير (Rôle Manager requis)</td><td>دورك في هذا المتجر لا يسمح بهذا الإجراء (استيراد، إعداد…).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/importer-catalogue-csv">استيراد الكتالوج من ملف CSV</a></td></tr><tr><td>يتطلب دور المدير في هذا المتجر (Rôle Manager requis sur ce magasin)</td><td>أنت أمين صندوق أو نادل في هذا المتجر، أو ليس لك دور فيه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/equipe">تكوين الفريق: الأدوار، الدعوات، رمز PIN</a></td></tr><tr><td>يتطلب دور المالك أو المسؤول (Rôle Propriétaire ou Administrateur requis)</td><td>إجراء مخصّص للمالك والمسؤولين.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/conformite-fiscale">المطابقة الجبائية: السلامة، الإقفالات، الأرشيف</a></td></tr></tbody></table><h2 id="lettre-s" tabindex="-1">S <a class="header-anchor" href="#lettre-s" aria-label="Permalink to &quot;S {#lettre-s}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>المالك وحده يمنح التفويض أو يلغيه. (Seul le propriétaire accorde ou révoque une délégation.)</td><td>المالك هو من يقرّر وصول فريق مساعدة Vendora.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/acces-vendora">السماح لفريق مساعدة Vendora (وصول مفوَّض)</a></td></tr><tr><td>مالك المتجر وحده يضبط موصِّلات الدفع (Seul le propriétaire du magasin configure les connecteurs de paiement)</td><td>المالك وحده يربط حسابات الدفع.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/caisse-paiements/connecteurs-de-paiement">ربط موصِّل دفع (جهاز الدفع الإلكتروني، الدفع عبر الإنترنت)</a></td></tr><tr><td>مالك المتجر وحده يحدّد نقطة البيع الرئيسية (Seul le propriétaire du magasin désigne la caisse principale)</td><td>المالك وحده يختار نقطة البيع الرئيسية للاستخلاص على الطاولة.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/appairer-un-appareil">إقران نقطة بيع أو هاتف (رمز، QR)</a></td></tr><tr><td>لا يمكن إغلاق إلا أمر مستلم جزئيًا. (Seul un bon reçu en partie peut être clôturé.)</td><td>أمر الشراء المستلم جزئيًا وحده له باقٍ يمكن إغلاقه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr><tr><td>يعدّل هذه البيانات المرجعية المالك والمسؤولون فقط. (Seuls le propriétaire et les administrateurs modifient ce référentiel.)</td><td>نسب الأداء على القيمة المضافة مخصّصة للمالك والمسؤولين.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/taux-de-tva">إدارة نسب الأداء على القيمة المضافة (الافتراضية، إعادة التعيين)</a></td></tr><tr><td>المخزون الأولي مُدخل مسبقًا: صحّحه بتعديل جرد (Stock initial déjà saisi : corrigez par un ajustement d&#39;inventaire)</td><td>لا يُدخل المخزون الأولي إلا مرة واحدة لكل منتج.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/valeur-du-stock">تقييم المخزون وإدخال المخزون الأولي</a></td></tr><tr><td>فائض بأكثر من 20 %: … — أكّد (Surplus de plus de 20 % : … — confirmez)</td><td>الكمية المستلمة تتجاوز الطلبية بكثير.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/bons-de-commande">إصدار أمر شراء واستلامه</a></td></tr></tbody></table><h2 id="lettre-t" tabindex="-1">T <a class="header-anchor" href="#lettre-t" aria-label="Permalink to &quot;T {#lettre-t}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>نسبة الأداء على القيمة المضافة 7 % غير موجودة في القائمة: أضفها في الكتالوج › نسب الأداء على القيمة المضافة (Taux de TVA 7 % absent du référentiel : ajoutez-le dans Catalogue › Taux de TVA)</td><td>النسبة المطلوبة غير موجودة بعد ضمن نسب الأداء على القيمة المضافة لديك.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/prix-par-magasin">الأسعار والتوفّر حسب المتجر</a></td></tr><tr><td>الهاتف مستعمل مسبقًا من قِبل … (Téléphone déjà utilisé par …)</td><td>حريف آخر لديه هذا الرقم بالفعل (تكرار محتمل).</td><td><a href="/VendoraSystem-docs/aide/ar/guide/clients/fiches-clients">إنشاء الحرفاء والعثور عليهم</a></td></tr><tr><td>أنهِ أولًا التحويلات الجارية لهذا المتجر: … (Terminez d&#39;abord les transferts en cours de ce magasin : …)</td><td>لا يمكن أرشفة متجر لديه تحويلات جارية.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/reglages/magasins">إدارة المتاجر (إنشاء، تعديل، أرشفة)</a></td></tr><tr><td>ثلاثة مستويات من الفئات كحدّ أقصى (Trois niveaux de catégories au plus)</td><td>تتداخل الفئات على ثلاثة مستويات كحد أقصى.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/categories">تنظيم الأصناف</a></td></tr></tbody></table><h2 id="lettre-u" tabindex="-1">U <a class="header-anchor" href="#lettre-u" aria-label="Permalink to &quot;U {#lettre-u}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>لا يمكن أن يكون لمنتج يُباع بالوزن متغيّرات (Un produit au poids ne peut pas avoir de variantes)</td><td>البيع بالوزن والمتغيّرات غير متوافقين في المنتج نفسه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/variantes">منتجات بمتغيّرات (المقاس، اللون، النكهة)</a></td></tr><tr><td>لا يُلغى التحويل المُرسَل: استلمه، مع فارق كامل عند الحاجة (Un transfert expédié ne s&#39;annule pas : réceptionnez-le, éventuellement avec un écart total)</td><td>بعد إرساله، ينتهي التحويل باستلامه.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/stock-achats/transferts">تحويل المخزون بين المتاجر</a></td></tr></tbody></table><h2 id="lettre-v" tabindex="-1">V <a class="header-anchor" href="#lettre-v" aria-label="Permalink to &quot;V {#lettre-v}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرسالة</th><th>السبب</th><th>ماذا تفعل</th></tr></thead><tbody><tr><td>تم تعديل المتغيّر في مكان آخر — أعد تحميل البطاقة. (Variante modifiée ailleurs — rechargez la fiche.)</td><td>عدّل شخص آخر المتغيّر.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/variantes">منتجات بمتغيّرات (المقاس، اللون، النكهة)</a></td></tr><tr><td>نسخة قديمة: الحالية …، المستلمة … (Version périmée : courante …, reçue …)</td><td>حفظت نسخة أقدم من نسخة الخادم (تعديل متزامن): أعد تحميل الصفحة وأعد التعديل.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/catalogue/creer-un-produit">إنشاء منتج وتعديله</a></td></tr><tr><td>العرض المباشر مخصّص لمديري هذا المتجر. (Vue en direct réservée aux managers de ce magasin.)</td><td>لوحة القيادة المباشرة مخصّصة للمديرين.</td><td><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/tableau-de-bord">التعرّف على لوحة القيادة وقائمة « بداية جيدة »</a></td></tr></tbody></table><h2 id="لم-تجد-رسالتك؟" tabindex="-1">لم تجد رسالتك؟ <a class="header-anchor" href="#لم-تجد-رسالتك؟" aria-label="Permalink to &quot;لم تجد رسالتك؟&quot;">​</a></h2><ul><li>اكتب بضع كلمات من الرسالة في <strong>البحث</strong> بمركز المساعدة: لكل درس قسمه الخاص « إذا لم ينجح الأمر » مع رسائل صفحته.</li><li>هل تظهر الرسالة على <strong>نقطة بيع</strong> أو <strong>هاتف القاعة</strong> أو <strong>شاشة المطبخ</strong> أو <strong>كشك</strong>؟ راجع <a href="/VendoraSystem-docs/aide/ar/guide/depannage/caisse-ne-synchronise-plus">نقطة بيع لم تعد تتزامن</a>، <a href="/VendoraSystem-docs/aide/ar/guide/depannage/pin-refuse">رمز PIN مرفوض أو مقفل</a> و <a href="/VendoraSystem-docs/aide/ar/guide/depannage/mise-a-jour-requise">« تحديث مطلوب » على الجهاز</a>.</li><li>ما زلت عالقًا؟ دوّن الرسالة كما هي والصفحة والوقت، ثم اتصل بدعم Vendora؛ ويمكن للمالك أيضًا <a href="/VendoraSystem-docs/aide/ar/guide/reglages/acces-vendora">السماح لفريق مساعدة Vendora</a> بالاطلاع على حسابك.</li></ul><h2 id="انظر-أيضًا" tabindex="-1">انظر أيضًا <a class="header-anchor" href="#انظر-أيضًا" aria-label="Permalink to &quot;انظر أيضًا&quot;">​</a></h2><ul><li><a href="/VendoraSystem-docs/aide/ar/guide/depannage/aide-contextuelle">المساعدة السياقية « ? »</a></li><li><a href="/VendoraSystem-docs/aide/ar/guide/bien-demarrer/se-reperer">التوجّه في لوحة الإدارة</a></li><li><a href="/VendoraSystem-docs/aide/ar/guide/depannage/">قسم استكشاف الأعطال / أسئلة شائعة</a></li></ul>',44))])}const y=d(l,[["render",c]]);export{V as __pageData,y as default};
